import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard';
import Footer from './components/Footer';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputPassword, setInputPassword] = useState('');

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch('http://localhost:5000/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: inputName, password: inputPassword })
      });
      const data = await response.json();
      if (data.status === 'Success') {
        setStudentName(inputName);
        setIsLoggedIn(true);
        setShowLoginModal(false);
        setCurrentPage('Dashboard');
      } else {
        alert('Invalid Username or Password!');
      }
    } catch (error) {
      alert('Error: Server connection failed!');
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setStudentName('');
    setInputName('');
    setInputPassword('');
    setCurrentPage('Home');
  };

  return (
    <div style={{ margin: 0, padding: 0, fontFamily: 'Arial, sans-serif', backgroundColor: '#f4f6f9', minHeight: '100vh' }}>
      <Navbar 
        onLoginClick={() => setShowLoginModal(true)} 
        isLoggedIn={isLoggedIn} 
        studentName={studentName} 
      />

      {currentPage === 'Home' && <Home />}
      {currentPage === 'Classes' && <Timetable />}
      {currentPage === 'Teachers' && <Teachers />}
      {currentPage === 'About' && <About />}
      {currentPage === 'Dashboard' && <LmsDashboard username={studentName} onLogout={handleLogout} />}

      <Footer />

   {/* Footer එකට පස්සේ Modal එක පටන් ගන්නා තැන */}
      {showLoginModal && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
          <div style={{ backgroundColor: '#ffffff', padding: '0', borderRadius: '20px', width: '700px', height: '400px', display: 'flex', overflow: 'hidden', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' }}>
            
            <div style={{ flex: 1, backgroundColor: '#2d6a4f', color: '#ffffff', padding: '40px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
              <h2>AuraPen Saku</h2>
              <p>Education Institute</p>
            </div>

            <div style={{ flex: 1, padding: '40px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
              <h3 style={{ color: '#2d6a4f' }}>Welcome Back!</h3>
              <form onSubmit={handleLoginSubmit}>
                <input type="text" placeholder="User Name" required onChange={(e) => setInputName(e.target.value)} style={{ width: '100%', padding: '10px', marginBottom: '15px', borderRadius: '10px', border: '1px solid #ddd' }} />
                <input type="password" placeholder="Password" required onChange={(e) => setInputPassword(e.target.value)} style={{ width: '100%', padding: '10px', marginBottom: '15px', borderRadius: '10px', border: '1px solid #ddd' }} />
                <button type="submit" style={{ width: '100%', padding: '12px', backgroundColor: '#2d6a4f', color: '#ffffff', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' }}>Login</button>
              </form>
            </div>
          </div>
        </div>
      )}
    </div> // මේක තමයි මුළු පේජ් එකම අල්ලලා ඉන්න ප්‍රධාන div එකේ අන්තිම ක්ලෝසින් එක
  );
}
